"use client"

// AsciiArt — "HANZO Biometric Braille", made with the 21st ASCII editor and baked
// to its exact rendered output (looping video + poster). Zero dependencies:
// one <video> that fills its parent. Drop it behind or inside your content:
// <div className="relative h-96"><AsciiArt className="absolute inset-0" /></div>
// Remix the source recipe (styles, animation, palette) in the editor:
// https://21st.dev/community/ascii/editor?from=4b609494-71b6-424d-a7b7-a4e913467945
export function AsciiArt({ className }: { className?: string }) {
  return (
    <video
      className={className}
      src={"https://assets.21st.dev/ascii-recipes/videos/user_3GPGUGW0kezwI1M261bFhugwynL/ac2a0ba7-9007-4bd7-bd20-3e8709a4fee6.mp4"}
      poster={"https://assets.21st.dev/ascii-recipes/thumbnails/user_3GPGUGW0kezwI1M261bFhugwynL/5fabfca4-d401-489c-9d26-fe4cd94237fb.webp"}
      autoPlay
      loop
      muted
      playsInline
      aria-label={"HANZO Biometric Braille — animated ASCII art"}
      style={{
        display: "block",
        width: "100%",
        height: "100%",
        objectFit: "cover",
      }}
    />
  )
}

